import csv
import os
import re
import stat
import sys
import tempfile


class MergeError(Exception):
    pass


def fail(message):
    print(f"merge: {message}", file=sys.stderr)
    return 1


def main():
    output = sys.argv[1]
    sources = sys.argv[2:]
    expected_header = None
    transaction_index = None
    records = {}

    try:
        output_stat = os.stat(output, follow_symlinks=False)
    except FileNotFoundError:
        output_stat = None
    else:
        if not stat.S_ISREG(output_stat.st_mode):
            raise MergeError(f"refusing to replace non-regular output {output}")

    for source in sources:
        try:
            stream = open(source, "r", encoding="utf-8-sig", newline="")
        except OSError as exc:
            raise MergeError(f"cannot open {source}: {exc.strerror}") from exc

        with stream:
            reader = csv.reader(stream, strict=True)
            try:
                header = next(reader)
            except StopIteration:
                raise MergeError(f"{source}: empty export")
            except csv.Error as exc:
                raise MergeError(f"{source}: invalid CSV header: {exc}") from exc

            if expected_header is None:
                expected_header = header
                if header.count("transaction_id") != 1:
                    raise MergeError(
                        f"{source}: header must contain transaction_id exactly once"
                    )
                transaction_index = header.index("transaction_id")
            elif header != expected_header:
                raise MergeError(f"{source}: header differs from the first export")

            try:
                for line_number, row in enumerate(reader, start=2):
                    if not row or all(value == "" for value in row):
                        continue
                    if len(row) != len(expected_header):
                        raise MergeError(
                            f"{source}:{line_number}: expected "
                            f"{len(expected_header)} fields, found {len(row)}"
                        )

                    raw_id = row[transaction_index].strip()
                    if re.fullmatch(r"[+-]?[0-9]+", raw_id) is None:
                        raise MergeError(
                            f"{source}:{line_number}: transaction_id "
                            f"{raw_id!r} is not an integer"
                        )
                    numeric_id = int(raw_id, 10)
                    data = tuple(
                        row[:transaction_index] + row[transaction_index + 1 :]
                    )

                    previous = records.get(numeric_id)
                    if previous is None:
                        records[numeric_id] = (row, data, source, line_number)
                    elif previous[1] != data:
                        raise MergeError(
                            "conflicting duplicate transaction_id "
                            f"{numeric_id}: {previous[2]}:{previous[3]} "
                            f"differs from {source}:{line_number}"
                        )
            except csv.Error as exc:
                raise MergeError(
                    f"{source}:{reader.line_num}: invalid CSV: {exc}"
                ) from exc

    output_dir = os.path.dirname(output)
    descriptor, temporary = tempfile.mkstemp(
        dir=output_dir, prefix=".merged.csv.", text=True
    )
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8", newline="") as stream:
            writer = csv.writer(stream, lineterminator="\n")
            writer.writerow(expected_header)
            for numeric_id in sorted(records):
                writer.writerow(records[numeric_id][0])
            stream.flush()
            os.fsync(stream.fileno())

        if output_stat is None:
            os.chmod(temporary, 0o644)
        else:
            os.chmod(temporary, stat.S_IMODE(output_stat.st_mode))
            if os.geteuid() == 0:
                os.chown(temporary, output_stat.st_uid, output_stat.st_gid)

        os.replace(temporary, output)
        temporary = None
    finally:
        if temporary is not None:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass


try:
    main()
except (MergeError, OSError, UnicodeError) as exc:
    sys.exit(fail(str(exc)))
